function validate([timePoints]) {
  if (!Array.isArray(timePoints) || timePoints.length < 2 || timePoints.length > 20000) return 'timePoints needs 2 to 2 * 10^4 times.';
  for (const time of timePoints) {
    const match = typeof time === 'string' ? /^(\d\d):(\d\d)$/.exec(time) : null;
    if (!match || Number(match[1]) > 23 || Number(match[2]) > 59) return 'Each time is "HH:MM" between "00:00" and "23:59".';
  }
  return null;
}

