function findMinDifference(timePoints) {
  const toMinutes = t => parseInt(t.split(':')[0], 10) * 60 + parseInt(t.split(':')[1], 10);
  let best = Infinity;
  for (let a = 0; a < timePoints.length; a++) {
    for (let b = a + 1; b < timePoints.length; b++) {
      const gap = Math.abs(toMinutes(timePoints[a]) - toMinutes(timePoints[b]));
      best = Math.min(best, gap, 1440 - gap);
    }
  }
  return best;
}

