function generate(rand, size) {
  const format = m => `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
  if (size === 'large') {
    return [Array.from({ length: 2000 }, () => format(Math.floor(rand() * 1440)))];
  }
  const n = 2 + Math.floor(rand() * 7);
  const mode = Math.floor(rand() * 3);
  const times = [];
  for (let k = 0; k < n; k++) {
    let m;
    if (mode === 0) m = Math.floor(rand() * 1440);
    else if (mode === 1) m = (1380 + Math.floor(rand() * 120)) % 1440;
    else m = Math.floor(rand() * 24) * 60;
    times.push(format(m));
  }
  return [times];
}
